def generate_corpus(output_path: Path):
    output_path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with open(output_path, "w", encoding="utf-8") as f:
        for domain, sentences in DATA_DOMAINS.items():
            f.write(f"# --- {domain} ---\n")
            for s in sentences:
                f.write(s.strip() + "\n")
                count += 1
    print(f"Corpus généré avec succès dans {output_path} : {count} phrases réparties en 8 domaines.")

if __name__ == "__main__":
    p = Path(__file__).resolve().parent.parent.parent / "data" / "corpus" / "corpus_genie_logiciel.txt"
    generate_corpus(p)
